  contact_permission                       TEXT,
  fv_worktype_last_upda                    TIMESTAMPTZ,
  first_name                               TEXT,
  last_name                                TEXT,
  international_location_number1           TEXT,
  legal_form                               TEXT,
  form_of_address                          TEXT,
  business_partner_data_origin_type        TEXT,
