  non_resident_company_origin_cntry        TEXT,
  business_partner_group_type              TEXT,
  last_change_date                         DATE,
  last_change_time                         TIME,
  synced_at                                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (business_partner)
);
